		pattern: mapped,
		schemavar: `nt${slot}.nspname`,
		namevar: `t${slot}.typname`,
		altnamevar: `pg_catalog.format_type(t${slot}.oid, NULL)`,
		visibilityrule: `pg_catalog.pg_type_is_visible(t${slot}.oid)`
