const cmdListDbRoleSettings = {
	name: "drds",
	run: async (ctx) => {
		const rolePat = ctx.nextArg("normal");
		const dbPat = rolePat ? ctx.nextArg("normal") : null;
		const c = conn(ctx);
		if (!c) return noConn(ctx);
		const query = listDbRoleSettings({
			pattern: rolePat ?? void 0,
			pattern2: dbPat ?? void 0,
			serverVersion: c.serverVersion
		});
		const results = [];
		const curDb = currentDb(c);
		if (rolePat !== null) {
			const r = processSQLNamePattern({
				namevar: "r.rolname",
				pattern: rolePat
			});
			const err = validatePattern(rolePat, r, 0, curDb);
			if (err !== null) {
				writeErr(`${err}\n`);
				return {
					status: "error",
					errorWritten: true
				};
			}
			results.push(r);
		}
		if (dbPat !== null) {
			const r = processSQLNamePattern({
				namevar: "d.datname",
				pattern: dbPat
			});
			const err = validatePattern(dbPat, r, 0, curDb);
			if (err !== null) {
				writeErr(`${err}\n`);
				return {
					status: "error",
					errorWritten: true
				};
			}
			results.push(r);
		}
		if (rolePat === null && dbPat === null) return runDualPatternList(ctx, query, results);
		const { sql, params } = applyTwoPatterns(query.sql, [], results);
		const finalQuery = {
			...query,
			sql,
			params
		};
		try {
			if ((await c.query(sql, params)).rows.length === 0 && !ctx.settings.quiet) {
				if (rolePat !== null && dbPat !== null) writeErr(`Did not find any settings for role "${rolePat}" and database "${dbPat}".\n`);
				else if (rolePat !== null) writeErr(`Did not find any settings for role "${rolePat}".\n`);
				return { status: "ok" };
			}
			await runListQuery(c, finalQuery, {
				schemaConditions: [],
				nameConditions: [],
				visibilityConditions: [],
				params: [],
				dotCount: 0,
				dbLiteral: null
			}, process.stdout, ctx.settings.popt);
			return { status: "ok" };
		} catch (err) {
			writeErr(`\\${ctx.cmdName}: ${errMsg(err)}\n`);
			return {
				status: "error",
				errorWritten: true
			};
		}
	}
};
